diff --git a/rust/fsl-core/tests/reviewgraphen_generated_calibration_06.rs b/rust/fsl-core/tests/reviewgraphen_generated_calibration_06.rs
new file mode 100644
--- /dev/null
+++ b/rust/fsl-core/tests/reviewgraphen_generated_calibration_06.rs
@@ -0,0 +1,23 @@
+// SPDX-License-Identifier: Apache-2.0
+
+use fsl_core::domain_kernel_source;
+use fsl_syntax::{SourceFile, SurfaceDocument, parse_document};
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let source = r#"
+domain SagaReferences {
+  saga Fulfillment {
+    step WaitForReply {
+      awaits any MissingReply
+    }
+  }
+}
+"#;
+    let parsed = parse_document(SourceFile::new(source)).expect("parse domain document");
+    let SurfaceDocument::Domain(domain) = parsed.surface else {
+        panic!("expected domain document");
+    };
+    let error = domain_kernel_source(&domain).expect_err("unknown awaited event must be rejected");
+    assert_eq!(error.message, "unknown domain event 'MissingReply'");
+}
